package dev.eugheist.tc4modern;
import net.minecraft.core.*;import net.minecraft.world.level.block.*;import net.minecraft.world.item.*;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import thaumcraft.api.aspects.*;
/** Disposable normal-world audit; no live player's worlds or biome data are accessed. */
@EventBusSubscriber(modid=TC4Modern.MODID)
public final class ForestServerAudit {
 static void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(!Boolean.getBoolean("tc4modern.forestAudit"))return;var server=event.getServer();var level=server.overworld();try{var biome=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.BIOME).getOrThrow(MagicalForestContent.BIOME);require(biome.value().getGrassColor(0,0)==5635969&&biome.value().getFoliageColor()==6750149&&biome.value().getWaterColor()==30702,"Original biome colours");var found=level.findClosestBiome3d(b->b.is(MagicalForestContent.BIOME),new BlockPos(0,70,0),6400,64,128);require(found!=null,"Naturally placed magical forest via climate source");var center=found.getFirst();int logs=0,branches=0,pods=0;for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++){var chunk=level.getChunk((center.getX()>>4)+dx,(center.getZ()>>4)+dz);for(var s:chunk.getSections())if(!s.hasOnlyAir())for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=0;y<16;y++){var state=s.getBlockState(x,y,z);if(state.is(net.minecraft.tags.BlockTags.LOGS)){logs++;if(state.hasProperty(RotatedPillarBlock.AXIS)&&state.getValue(RotatedPillarBlock.AXIS)!=Direction.Axis.Y)branches++;}if(state.is(BasicsContent.MANA_POD.get()))pods++;}}require(logs>0&&branches>0,"Original tall oak branching generated");require(pods>0,"Natural mana pods under forest branches");
 var base=new BlockPos(center.getX(),200,center.getZ());var chunk=level.getChunkAt(base);chunk.fillBiomesFromNoise((x,y,z,sampler)->biome,level.getChunkSource().randomState().sampler());chunk.setUnsaved(true);var a=base;var b=base.east();for(var at:java.util.List.of(a,b)){level.setBlock(at.above(),Blocks.OAK_LOG.defaultBlockState(),3);level.setBlock(at,BasicsContent.MANA_POD.get().defaultBlockState().setValue(ManaPodBlock.AGE,2),3);}var first=(ManaPodEntity)level.getBlockEntity(a);var second=(ManaPodEntity)level.getBlockEntity(b);first.aspect=Aspect.AIR;second.aspect=Aspect.FIRE;boolean bred=false;for(int i=0;i<40;i++){level.setBlock(a,first.getBlockState().setValue(ManaPodBlock.AGE,2),3);first.aspect=Aspect.AIR;first.grow();if(first.aspect==Aspect.LIGHT)bred=true;}require(bred,"Adjacent Aer/Ignis produce Lux");while(first.getBlockState().getValue(ManaPodBlock.AGE)<7)first.grow();require(first.getBlockState().canSurvive(level,a),"Magical-biome pod survival");var snapshot=first.saveWithoutMetadata(level.registryAccess());var restored=new ManaPodEntity(a,first.getBlockState());restored.loadWithComponents(snapshot,level.registryAccess());require(restored.aspect==first.aspect,"Pod aspect persistence");var drops=Block.getDrops(first.getBlockState(),level,a,first);require(drops.size()==1&&drops.get(0).getCount()>=1&&drops.get(0).getCount()<=2&&ManaBeanItem.aspect(drops.get(0))==first.aspect,"Ripe pod drop carries aspect");
 var player=net.neoforged.neoforge.common.util.FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("ed678c25-9da3-4376-9491-8f7f0b6e8e99"),"TC4ForestAudit"));player.setPos(base.getX(),200,base.getZ());player.setInvulnerable(true);for(int i=0;i<80;i++){player.removeAllEffects();var bean=ManaBeanItem.of(Aspect.AIR,1);bean.getItem().finishUsingItem(bean,level,player);}require(ResearchKnowledge.points(player.getPersistentData(),"aer")>0,"Eating beans awards aspect points");require(BasicsPotionSlots.pick(31)==TC4Modern.FLUX_TAINT&&BasicsPotionSlots.pick(39)==WarpEffects.THAUMARHIA&&BasicsPotionSlots.pick(30)==null,"Extended original40 potion slots");
 var ops=level.registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE);for(String name:new String[]{"simple_dungeon","desert_pyramid","jungle_temple","abandoned_mineshaft","stronghold_library"}){var key=net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.LOOT_TABLE,net.minecraft.resources.ResourceLocation.withDefaultNamespace("chests/"+name));var table=server.reloadableRegistries().getLootTable(key);var text=net.minecraft.world.level.storage.loot.LootTable.DIRECT_CODEC.encodeStart(ops,table).getOrThrow().toString();require(text.contains("tc4modern:knowledge_fragment"),"Fragment chest loot "+name);}
 String report="PASS: native climate forest at "+center+"; 25 chunks logs="+logs+" branches="+branches+" natural pods="+pods+"; original colours; growth/Lux breeding/NBT/ripe drops/eating;40potion slots; five chest tables contain fragments\n";java.nio.file.Files.writeString(java.nio.file.Path.of("forest-audit.txt"),report);System.out.print("TC4_FOREST_AUDIT "+report);
 }catch(Exception ex){throw new IllegalStateException("Forest audit failed",ex);}finally{server.halt(false);}}
}
